  const books={KKA:'EET2025KKA1008(1).pdf',TA:'EET2025TA1005(1).pdf',PP:'EET2025PP1232-panoSimgeler(1).pdf',KP:'EET2025KP1115-pano(1).pdf',PA:'EET2025PA1113-pano(1).pdf'};
  const bookSource=(book,pages,basis)=>({file:books[book],pages:String(pages),basis,pageNumbering:'PDF'});
  const TB=(a='1',b='2',w=80,h=100)=>[P(a,a,w/2,0,'top'),P(b,b,w/2,h,'bottom')];
  const rows=(top,bottom,w=120,h=120)=>[...top.map((id,i)=>P(id,id,20+i*20,0,'top')),...bottom.map((id,i)=>P(id,id,20+i*20,h,'bottom'))];
  function bookEntry(id,name,group,glyph,source,pins=TB(),extra={}){
    const d={id,name,category:'Belge sembolleri',catalogGroup:group,model:'PDF s. '+source.pages,kind:'diagram',w:80,h:100,pins,
      orientation:'vertical',wireOrientation:'V',bookSymbol:glyph,symbolSource:source,library:'MEB belge sembolleri',standard:'Belge gösterimi',
      symbolCode:'BOOK-'+id.toUpperCase(),diagramOnly:true,materialSymbol:true,...extra};
    classic.push(d);return d;
  }
  const pp137=bookSource('PP',137,'Kumanda sembolleri tablosu'),kp117=bookSource('KP',117,'Tablo 4.1 · sensör ve kumanda sembolleri'),pa19=bookSource('PA',19,'Tablo 1.1 · TSE devre sembolü');
